            game.xwPlayPlayerAudioRand = function (name) {
                //alert(name);
                var skills = lib.character[name][3];
                skills = skills.slice(0);
                if (skills && skills.length) {
                    skills.remove('xwjh_audiozhenwang');
                    var skill = skills.randomGet();
                    if (skill) {
                        game.xwTrySkillAudio(skill, { name: name }, true);
                    }
                }
            };
            game.xwTrySkillAudio = function (skill, player, directaudio, which) {
                //alert(skill+" "+player.name);
                var info = get.info(skill);
                if (!info) return;
                if (true) {
                    var audioname = skill;
                    if (info.audioname2 && info.audioname2[player.name]) {
                        audioname = info.audioname2[player.name];
                        info = lib.skill[audioname];
                    }
                    var audioinfo = info.audio;
                    if (typeof audioinfo == 'string' && lib.skill[audioinfo]) {
                        audioname = audioinfo;
                        audioinfo = lib.skill[audioname].audio;
                    }
                    if (typeof audioinfo == 'string') {
                        //alert('8');
                        if (audioinfo.indexOf('ext:') == 0) {
                            //alert('9');
                            audioinfo = audioinfo.split(':');
                            if (audioinfo.length == 3) {
                                if (audioinfo[2] == 'true') {
                                    //alert('1');
                                    game.playAudio('../extension', audioinfo[1], audioname);
                                } else {
                                    audioinfo[2] = parseInt(audioinfo[2]);
                                    if (audioinfo[2]) {
                                        if (which) {
                                            //alert('2');
                                            game.playAudio('../extension', audioinfo[1], audioname + ((which % audioinfo[2]) + 1));
                                        } else {
                                            //alert('3');
                                            game.playAudio('../extension', audioinfo[1], audioname + Math.ceil(audioinfo[2] * Math.random()));
                                        }
                                    }
                                }
                            }
                            return;
                        }
                    } else if (Array.isArray(audioinfo)) {
                        audioname = audioinfo[0];
                        audioinfo = audioinfo[1];
                    }
                    if (Array.isArray(info.audioname) && player) {
                        if (info.audioname.includes(player.name)) {
                            audioname += '_' + player.name;
                        } else if (info.audioname.includes(player.name1)) {
                            audioname += '_' + player.name1;
                        } else if (info.audioname.includes(player.name2)) {
                            audioname += '_' + player.name2;
                        }
                    }
                    if (typeof audioinfo == 'number') {
                        if (which) {
                            //alert('4');
                            game.playAudio('skill', audioname + ((which % audioinfo) + 1));
                        } else {
                            //alert('5');
                            game.playAudio('skill', audioname + Math.ceil(audioinfo * Math.random()));
                        }
                    } else if (audioinfo) {
                        //alert('6');
                        game.playAudio('skill', audioname);
                    } else if (true && info.audio !== false) {
                        game.playSkillAudio(audioname);
                    }
                }
            };
            window.xwTrySkillAudio = game.xwTrySkillAudio;
            lib.element.player.isXuanwujianghu = function () {
                if (this.name) {
                    return lib.characterPack['玄武江湖'][this.name];
                }
                if (this.name1) {
                    return lib.characterPack['玄武江湖'][this.name1];
                }
                return false;
            };
            lib.element.player.xwHasCanSaveFriend = function (toushi) {
                var player = this;
                return (
                    game.countPlayer(function (current) {
                        if (current == player) return false;
                        if (get.attitude(current, player) <= 0) return false;
                        if (current.hasSkillTag('xwSave', null, { target: player })) {
                            return true;
                        }
                        if (toushi) {
                            if (current.hasCard('tao', 'h')) return true;
                        }
                        if (current.countCards('h') > 0) return true;
                        return false;
                    }) > 0
                );
            };
            lib.element.player.xwLearn = function (miji) {
                var target = this;
                if (!target.hasSkill('xwjh_mijijineng')) {
                    target.addSkill('xwjh_mijijineng');
                }
                var b = get.xwIsNeigong(miji);
                var has = b ? get.xwHasNeigong(target) : get.xwHasWaigong(target);
                if (!has) {
                    for (var i = 0; i < target.storage.xwjh_mijijineng.length; i++) {
                        var sk = target.storage.xwjh_mijijineng[i];
                        if (b && get.xwIsNeigong(sk)) {
                            target.storage.xwjh_mijijineng.splice(i, 1);
                            i--;
                        } else if (!b && get.xwIsWaigong(sk)) {
                            target.storage.xwjh_mijijineng.splice(i, 1);
                            i--;
                        }
                    }
                    target.storage.xwjh_mijijineng.push(miji);
                    target.addAdditionalSkill('xwjh_mijijineng', miji, true);
                    game.log(target, '习得技能【', miji, '】.');
                    game.playXwAudio('xwjh_mijipai', 1);
                } else {
                    var sname = b ? get.xwNeigong(target) : get.xwWaigong(target);
                    game.log(target, '已经习得', b ? '内功' : '外功', '【', sname, '】,不能再次习得.');
                }
            };
            get.xwGuess = function (truth, rateTrueToFalse, rateFalseToTrue) {
                if (truth) {
                    return Math.random() > rateTrueToFalse;
                } else {
                    return Math.random() < rateFalseToTrue;
                }
            };
            lib.element.player.xwGuessHaveCard = function (cardname, respond) {
                if (this.countCards('h') == 0) {
                    if (cardname == 'sha' && !this.hasSkillTag('respondSha', true, respond ? 'respond' : 'use', true)) {
                        return false;
                    }
                    if (cardname == 'shan' && !this.hasSkillTag('respondShan', true, null, true)) {
                        return false;
                    }
                }
                var truth;
                if (cardname == 'sha') {
                    truth = this.hasSha();
                } else if (cardname == 'shan') {
                    truth = this.hasShan();
                } else {
                    truth = this.hasUsableCard(cardname);
                }
                var base = this.countCards('h');
                if (base <= 0) return false;
                var rateFalseToTrue = 0.08 * base;
                var rateTrueToFalse = 0.8 / base;
                return get.xwGuess(truth, rateTrueToFalse, rateFalseToTrue);
            };
            var originChangeGroup = lib.element.player.changeGroup;
            lib.element.player.changeGroup = function (group) {
                var originGroup = this.group;
                originChangeGroup.apply(this, arguments);
                if (this.isXuanwujianghu()) {
                    var obj = {
                        xwjh_zheng: 'xwjh_tongkai',
                        xwjh_xie: 'xwjh_pengbi',
                        xwjh_chao: 'xwjh_zhongzhu',
                        xwjh_ye: 'xwjh_wuju',
                    };
                    if (this.hasSkill(obj[originGroup])) {
                        this.removeSkill(obj[originGroup]);
                        this.addSkill(obj[group]);
                    }
                }
            };
