            game.playAudio = function (...args) {
                const str = args.join('/');
                if (str.includes('玄武江湖')) {
                    if (str.includes('xwjh_audiozhenwang')) {
                        if (_status.xwCurrentViewIntro) {
                            game.playXwAudio(_status.xwCurrentViewIntro);
                            return;
                        }
                    }
                    if (_status.event && _status.event.name == 'useCard' && str.includes(_status.event.card.name)) {
                        var player = _status.event.player;
                        var sex = player.xwPrimarySex() ? player.xwPrimarySex() : player.sex;
                        if (sex != 'male') sex = 'female';
                        game.originPlayAudio_xw('../extension/玄武江湖/audio', _status.event.card.name + '_' + sex);
                        return;
                    }
                    if (str.includes('xwjh_niyin')) {
                        game.xwPlayPlayerAudioRand(
                            Object.keys(lib.character)
                                .filter(function (name) {
                                    return name.indexOf('xwjh_') == 0 && name != 'xwjh_epu' && name.indexOf('xwjh_boss_') != 0 && name.indexOf('xwjh_zong_') != 0 && name.indexOf('xwjh_jixiangwu_') != 0;
                                })
                                .randomGet()
                        );
                        return;
                    }
                }
                if (str.includes('effect')) {
                    if (str.includes('damage')) {
                        if (_status.event && _status.event.name == 'damage' && _status.event.card && _status.event.card.name == 'xwjh_card_wushisanke') {
                            game.playXwAudio('xwjh_voc_kantou');
                            return;
                        }
                    }
                    if (str.includes('equip')) {
                        if (_status && _status.event) {
                            var event = _status.event;
                            if (event.name == 'equip') {
                                var card = event.card;
                                if (card) {
                                    var vocname = equipVoices[card.name];
                                    if (vocname) {
                                        game.playXwAudio(vocname);
                                        return;
                                    }
                                }
                            }
                        }
                    }
                    if (lib.config.xwWinMusic !== false) {
                        if (str.includes('win')) {
                            if (
                                !game.hasPlayer(function (current) {
                                    return !current.isXuanwujianghu();
                                })
                            ) {
                                game.playXwAudio('xwjh_voc_win');
                                return;
                            }
                        }
                        if (str.includes('lose')) {
                            if (
                                !game.hasPlayer(function (current) {
                                    return !current.isXuanwujianghu();
                                })
                            ) {
                                game.playXwAudio('xwjh_voc_lose');
                                return;
                            }
                        }
                    }
                }//QQQ
                if (str.includes('card') && _status.event && _status.event.name == 'useCard') {
                    var player = _status.event.player;
                    var sex = player.xwPrimarySex() ? player.xwPrimarySex() : player.sex;
                    if (sex != 'male') sex = 'female';
                }
                game.originPlayAudio_xw.apply(this, args);
            };
            game.xwPlayJuqingAudio = function (name) {
                var audio = game.xwPlayAudioRepeatable('../extension/玄武江湖/audio', name);
                if (_status.xwJuqingAudio) {
                    _status.xwJuqingAudio.remove();
                }
                _status.xwJuqingAudio = audio;
            };
            game.xwPlayAudioRepeatable = function (...args) {
                const str = args.join('/');
                _status.skillaudio.add(str);
                game.addVideo('playAudio', null, str);
                setTimeout(function () {
                    _status.skillaudio.remove(str);
                }, 1000);
                var audio = document.createElement('audio');
                audio.autoplay = true;
                audio.volume = lib.config.volumn_audio / 8;
                if (str.includes('.mp3') || str.includes('.ogg')) {
                    audio.src = 'audio' + str;
                } else {
                    audio.src = 'audio' + str + '.mp3';
                }
                audio.addEventListener('ended', function () {
                    this.remove();
                });
                audio.onerror = function () {
                    if (this._changed) {
                        this.remove();
                    } else {
                        this.src = 'audio' + str + '.ogg';
                        this._changed = true;
                    }
                };
                ui.window.appendChild(audio);
                return audio;
            };
