            lib.element.player.xwAddTempSkillForEvent = function (skill, event, triggername, checkConflict) {
                if (this.hasSkill(skill) && this.tempSkills[skill] == undefined) return;
                var noremove = this.skills.includes(skill);
                this.addSkill(skill, checkConflict, true);
                if (!noremove) this.skills.remove(skill);
                if (!this.tempSkills[skill]) {
                    this.tempSkills[skill] = function (event2, player2, name2) {
                        if (name2 != triggername) return false;
                        if (event2 !== event) return false;
                        return true;
                    };
                } else {
                    var originExpire = this.tempSkills[skill];
                    this.tempSkills[skill] = function (event2, player2, name2) {
                        if (originExpire == name2) return true;
                        if (Array.isArray(originExpire) && originExpire.includes(name2)) return true;
                        if (typeof originExpire === 'function' && originExpire(event2, player2, name2)) return true;
                        if (name2 != triggername) return false;
                        if (event2 !== event) return false;
                        return true;
                    };
                }
                lib.hookmap[triggername] = true;
            };
