            let originGroupSort = lib.sort.group;
            lib.sort.group = function (a, b) {
                let ax = a.indexOf('xwjh_');
                let bx = b.indexOf('xwjh_');
                if (ax == 0 && bx != 0) {
                    return -1;
                }
                if (ax != 0 && bx == 0) {
                    return 1;
                }
                if (ax != 0 && bx != 0) {
                    return originGroupSort(a, b);
                }
                var groupValue = {
                    xwjh_zheng: 1,
                    xwjh_xie: 2,
                    xwjh_chao: 3,
                    xwjh_ye: 4,
                    xwjh_zong: 5,
                    xwjh_xian: 6,
                };
                return groupValue[a] - groupValue[b];
            };
