                shanyuediao: '<font color="#0000FF">山月调(古剑奇谭三)</font>',
                changyinfengcao: '<font color="#0000FF">长荫丰草(古剑奇谭三)</font>',
                chizizhijian: "<font color='#0000FF'>赤子之剑(古剑奇谭三)</font>",
