            game.xwYiIsMove = function () {
                return ['identity', 'guozhan', 'xuanwuvs', 'xwjuqing', 'xwxiahun'].includes(get.mode());
            };
            game.xwCopyFilesFromDirToDirWithFold = function (fromPath, toPath, process, callback, errorContinue) {
                game.getFileList(fromPath, function (folder, files) {
                    game.xwCopyFilesFromDirToDir(
                        fromPath,
                        toPath,
                        files,
                        function () {
                            var folderList = folder.slice(0);
                            var finish = function () {
                                if (callback) {
                                    callback(true);
                                }
                            };
                            if (folderList.length == 0) {
                                finish();
                            }
                            for (var f of folder) {
                                (function (f) {
                                    game.ensureDirectory(toPath + '/' + f, function () {
                                        game.xwCopyFilesFromDirToDirWithFold(
                                            fromPath + '/' + f,
                                            toPath + '/' + f,
                                            process,
                                            function (ret) {
                                                if (!ret) {
                                                    if (!errorContinue) {
                                                        return;
                                                    }
                                                }
                                                folderList.remove(f);
                                                if (folderList.length == 0) {
                                                    finish();
                                                }
                                            },
                                            errorContinue
                                        );
                                    });
                                })(f);
                            }
                        },
                        null,
                        process,
                        errorContinue
                    );
                });
            };
            game.xwCopyFilesFromDirToDir = function (fromPath, toPath, list, callback, namefilter, process, errorContinue) {
                if (!game.readFile || !game.writeFile) {
                    if (callback) {
                        callback(false);
                    }
                    return;
                }
                if (typeof list == 'string') {
                    var from = fromPath + '/' + list;
                    game.readFile(
                        from,
                        function (data) {
                            var name = list;
                            if (namefilter) {
                                name = namefilter(name);
                            }
                            game.writeFile(data, toPath, name, function () {
                                if (process) {
                                    process(name);
                                }
                                if (callback) {
                                    callback(true);
                                }
                            });
                        },
                        function (err) {
                            if (callback) {
                                callback(false);
                            }
                        }
                    );
                    return;
                }
                if (list.length == 0) {
                    if (callback) {
                        callback(true);
                    }
                    return;
                }
                var lst = list.slice(0);
                var name = lst.shift();
                game.xwCopyFilesFromDirToDir(
                    fromPath,
                    toPath,
                    name,
                    function (success) {
                        if (!success) {
                            if (callback) {
                                callback(false);
                            }
                            if (!errorContinue) {
                                return;
                            }
                        }
                        game.xwCopyFilesFromDirToDir(
                            fromPath,
                            toPath,
                            lst,
                            function (success) {
                                if (callback) {
                                    callback(success);
                                }
                            },
                            namefilter,
                            process,
                            errorContinue
                        );
                    },
                    namefilter,
                    process,
                    errorContinue
                );
            };
            game.xwPlayAnimOnCard = function (name, card, repeat, abis) {
                if (!repeat) repeat = 1;
                if (!get.xwAnimOpen()) return;
                var anim = game.xwAnim.createAnim(name);
                var rect = card.getBoundingClientRect();
                if (!abis) {
                    anim.style.left = rect.left + rect.width / 2 - anim.xwjh_animation.width / 2 + 'px';
                    anim.style.top = rect.top + rect.height / 2 - anim.xwjh_animation.height / 2 + 'px';
                } else {
                    if (abis.left) {
                        anim.style.left = rect.left + rect.width / 2 - anim.xwjh_animation.width / 2 + abis.left + 'px';
                    } else {
                        anim.style.left = rect.left + rect.width / 2 - anim.xwjh_animation.width / 2 + 'px';
                    }
                    if (abis.top) {
                        anim.style.top = rect.top + rect.height / 2 - anim.xwjh_animation.height / 2 + abis.top + 'px';
                    } else {
                        anim.style.top = rect.top + rect.height / 2 - anim.xwjh_animation.height / 2 + 'px';
                    }
                }
                document.body.appendChild(anim);
                anim.xwjh_animation_play(function () {
                    if (repeat > 1) {
                        game.xwPlayAnimOnPlayer(name, card, repeat - 1, abis);
                    }
                    document.body.removeChild(anim);
                    anim.delete();
                });
            };
            game.xwjh_handleRect = function (rect) {
                return {
                    width: rect.width / game.documentZoom,
                    height: rect.height / game.documentZoom,
                    left: rect.left / game.documentZoom,
                    top: rect.top / game.documentZoom,
                    bottom: rect.bottom / game.documentZoom,
                    right: rect.right / game.documentZoom,
                };
            };
            game.xwPlayAnimOnPlayer = function (name, player, repeat, abis) {
                if (!repeat) repeat = 1;
                if (!get.xwAnimOpen()) return;
                var anim = game.xwAnim.createAnim(name);
                var rect = game.xwjh_handleRect(player.getBoundingClientRect());
                if (!abis) {
                    anim.style.left = rect.left + rect.width / 2 - anim.xwjh_animation.width / 2 + 'px';
                    anim.style.top = rect.top + rect.height / 2 - anim.xwjh_animation.height / 2 + 'px';
                } else {
                    if (abis.left) {
                        anim.style.left = rect.left + rect.width / 2 - anim.xwjh_animation.width / 2 + abis.left + 'px';
                    } else {
                        anim.style.left = rect.left + rect.width / 2 - anim.xwjh_animation.width / 2 + 'px';
                    }
                    if (abis.top) {
                        anim.style.top = rect.top + rect.height / 2 - anim.xwjh_animation.height / 2 + abis.top + 'px';
                    } else {
                        anim.style.top = rect.top + rect.height / 2 - anim.xwjh_animation.height / 2 + 'px';
                    }
                }
                document.body.appendChild(anim);
                anim.xwjh_animation_play(function () {
                    if (repeat > 1) {
                        game.xwPlayAnimOnPlayer(name, player, repeat - 1, abis);
                    }
                    document.body.removeChild(anim);
                    anim.delete();
                });
            };
            game.xwPlayAnimOnPlayerRepeat = function (name, player) {
                if (!get.xwAnimOpen())
                    return {
                        xwjh_animation_stop() { },
                    };
                var anim = game.xwAnim.createAnim(name);
                var rect = player.getBoundingClientRect();
                anim.style.left = rect.left + rect.width / 2 - anim.xwjh_animation.width / 2 + 'px';
                anim.style.top = rect.top + rect.height / 2 - anim.xwjh_animation.height / 2 + 'px';
                document.body.appendChild(anim);
                anim.xwjh_animation_play_repeat();
                return anim;
            };
            game.xwPlayAnimOnScreen = function (name) {
                if (!get.xwAnimOpen()) return;
                var anim = game.xwAnim.createAnim(name);
                anim.style.left = '50%';
                anim.style.top = '50%';
                anim.style.transform = 'translate(-50%,-50%)';
                document.body.appendChild(anim);
                anim.xwjh_animation_play(function () {
                    document.body.removeChild(anim);
                    anim.delete();
                });
            };
            lib.xwjh_animation_helper = function (beginValue, endValue, duration, frameLength, onFrame, onEnd) {
                var timestampBegin = new Date().getTime();
                var state = {
                    id: null,
                    end: false,
                    endAnim() {
                        this.end = true;
                        clearInterval(this.id);
                    },
                };
                state.id = setInterval(function () {
                    if (state.end) {
                        clearInterval(state.id);
                        return;
                    }
                    var timestamp = new Date().getTime();
                    var passTime = timestamp - timestampBegin;
                    if (passTime >= duration) {
                        state.end = true;
                        if (onEnd) {
                            onEnd();
                        }
                        clearInterval(state.id);
                        return;
                    }
                    var r = passTime / duration;
                    var val = (endValue - beginValue) * r + beginValue;
                    if (onFrame) {
                        onFrame(val);
                    }
                }, frameLength);
                return state;
            };
            lib.init.js = function (path, file, onload, onerror) {
                if (path[path.length - 1] == '/') {
                    path = path.slice(0, path.length - 1);
                }
                if (path == 'mode' && lib.config.all.stockmode.indexOf(file) == -1) {
                    if (_status.xwjh_jstoload && _status.xwjh_jstoload.includes(file)) {
                        lib.init['setMode_' + file](function () {
                            onload();
                            _status.xwjh_jstoload.remove(file);
                        });
                    } else {
                        lib.init['setMode_' + file]();
                        onload();
                    }
                    return;
                }
                if (Array.isArray(file)) {
                    for (var i = 0; i < file.length; i++) {
                        lib.init.js(path, file[i], onload, onerror);
                    }
                } else {
                    var script = document.createElement('script');
                    if (!file) {
                        script.src = path;
                    } else {
                        script.src = path + '/' + file + '.js';
                    }
                    if (path.indexOf('http') == 0) {
                        script.src += '?rand=' + get.id();
                        script.addEventListener('load', function () {
                            script.remove();
                        });
                    }
                    document.head.appendChild(script);
                    if (typeof onload == 'function') {
                        script.addEventListener('load', onload);
                        script.addEventListener('error', onerror);
                    }
                    return script;
                }
            };
