                        xwjh_card_yi: {
                            image: 'ext:玄武江湖/xwjh_card_yi.png',
                            audio: 'ext:玄武江湖',
                            type: 'basic',
                            fullskin: true,
                            usable: 1,
                            selectTarget: 1,
                            filterTarget(card, player, target) {
                                return player != target;
                            },
                            enable(card, player) {
                                if (player.hasSkillTag('xwLinkCanYi')) return true;
                                return !player.isLinked();
                            },
                            modTarget(card, player, target) {
                                return false;
                            },
                            async content(event, trigger, player) {
                                if (game.xwYiIsMove()) {
                                    if (!get.xwIsRandomPhase()) {
                                        if (!player.storage.xwjh_moveback) {
                                            player.storage.xwjh_moveback = [];
                                        }
                                        player.storage.xwjh_moveback.push(event.target);
                                    }
                                    game.swapSeat(player, event.target);
                                    game.playXwAudio('xwjh_voc_yi');
                                    if (player == game.me) {
                                        window.xwTempGainAchievement('count_50_轻功大师');
                                    }
                                } else {
                                    player.addTempSkill('xwjh_yi_cannot_swap', 'phaseAfter');
                                    player.storage.xwjh_yi_cannot_swap.push(event.target);
                                }
                            },
                            ai: {
                                basic: {
                                    order: 8,
                                    useful: 1,
                                    value: 2,
                                },
                                result: {
                                    player(player, target) {
                                        var event = _status.event;
                                        if (!event.xwYiEffectComputeCache) {
                                            event.xwYiEffectComputeCache = {};
                                        }
                                        var keyEffect = player.playerid + '-' + target.playerid;
                                        if (event.xwYiEffectComputeCache[keyEffect]) {
                                            return event.xwYiEffectComputeCache[keyEffect];
                                        }
                                        if (get.xwIsRandomPhase()) {
                                            var att1 = get.attitude(player, target.previous);
                                            var att2 = get.attitude(player, target.next);
                                            if (player.hp <= 1) {
                                                return att1 > 0 && att2 > 0 ? 3 : 0;
                                            } else if (player.hp >= 3 && player.hasSha()) {
                                                return att1 < 0 || att2 < 0 ? 1 : 0;
                                            }
                                            return 0;
                                        }
                                        if (!player.isPhaseUsing()) return 0;
                                        if (!game.xwYiIsMove()) {
                                            return 0;
                                        }
                                        if (!event) {
                                            return 0;
                                        }
                                        if (!event.xwYiEffectCache) {
                                            event.xwYiEffectCache = {};
                                        }
                                        if (!event.xwCanUseCache) {
                                            event.xwCanUseCache = {};
                                        }
                                        var getCacheCanUse = function (m, a, b1, b2) {
                                            var key = '';
                                            key += m.cardid;
                                            key += '-';
                                            key += a.playerid;
                                            key += '-';
                                            key += b1;
                                            key += '-';
                                            key += b2;
                                            var ret = event.xwCanUseCache[key];
                                            if (ret === undefined) {
                                                ret = player.canUse(m, a, b1, b2);
                                                event.xwCanUseCache[key] = ret;//QQQ
                                            }
                                            return ret;
                                        };
                                        var getCacheEffect = function (a, c, b, d) {
                                            var key = '';
                                            key += a.playerid;
                                            key += '-';
                                            key += c.cardid;
                                            key += '-';
                                            key += b.playerid;
                                            key += '-';
                                            key += d.playerid;
                                            key += '-';
                                            var ret = event.xwYiEffectCache[key];
                                            if (ret === undefined) {
                                                ret = get.effect(a, c, b, d);
                                                event.xwYiEffectCache[key] = ret;
                                            }
                                            return ret;
                                        };
                                        var plcv = 0;
                                        if (!plcv) {
                                            plcv = 0;
                                            var found = { status: false };
                                            if (
                                                player.countCards('h', function (card) {
                                                    if (found.status) {
                                                        return false;
                                                    }
                                                    if (
                                                        (card.name == 'sha' || ['trick', 'xwjh_anqi'].includes(get.type(card, 'delay'))) &&
                                                        game.countPlayer(function (current) {
                                                            if (current == player || current == target) return false;
                                                            if (get.xwDistanceSwap(player, target, current) > 1) return false;
                                                            var eff = getCacheEffect(current, card, player, player);
                                                            return (
                                                                current != player &&
                                                                getCacheCanUse(card, current, false, true) &&
                                                                !getCacheCanUse(card, current, true, true) &&
                                                                eff > 0 &&
                                                                !game.hasPlayer(function (current2) {
                                                                    return current2 != player && current2 != current && getCacheCanUse(card, current2, true, true) && getCacheEffect(current2, card, player, player) >= eff;
                                                                })
                                                            );
                                                        })
                                                    ) {
                                                        found.status = true;
                                                        return true;
                                                    }
                                                    return false;
                                                })
                                            ) {
                                                plcv += 2;
                                            }
                                        }
                                        event.xwYiEffectComputeCache[keyEffect] = plcv;
                                        return plcv;
                                    },
                                    target(player, target) {
                                        if (!game.xwYiIsMove()) {
                                            if (get.attitude(player, target) < 0 && get.distance(player, target) > 1) {
                                                return -1;
                                            }
                                        }
                                        return 0;
                                    },
                                },
                            },
                        },
