                        xwjh_card_toutianhuanri: {
                            image: 'ext:玄武江湖/xwjh_card_toutianhuanri.png',
                            audio: 'ext:玄武江湖',
                            type: 'trick',
                            fullskin: true,
                            selectTarget: 1,
                            enable(card, player) {
                                return !player.hasSkill('xwjh_toutianhuanrioff');
                            },
                            filterTarget(card, player, target) {
                                if (player == target) return false;
                                return target.countGainableCards(player, 'hej') > 0;
                            },
                            content() {
                                'step 0';
                                if (!player.hasSkill('xwjh_toutianhuanrioff')) {
                                    player.addSkill('xwjh_toutianhuanrioff');
                                }
                                if (target.countGainableCards(player, 'hej')) {
                                    player.gainPlayerCard('hej', target, true);
                                }
                                ('step 1');
                                if (event.cards && event.cards.length) {
                                    if (Array.isArray(event.cards))
                                        for (var i of event.cards) {
                                            //QQQ
                                            if (get.position(i, true) != 'o') {
                                                target.draw();
                                            }
                                        }
                                    target.gain(event.cards, 'gain2');
                                } else {
                                    target.draw();
                                }
                            },
                            ai: {
                                tag: {
                                    xwGain: 1,
                                },
                                wuxie(target, card, player, viewer) {
                                    if ((player == game.me || player.hasSkill('xwjh_daoyi')) && get.attitude(viewer, player) > 0) {
                                        return 0;
                                    }
                                },
                                basic: {
                                    order() {
                                        return 6.5;
                                    },
                                    useful: 3,
                                    value: 6,
                                },
                                result: {
                                    target(player, target) {
                                        if (get.attitude(player, target) <= 0)
                                            return target.countCards('he', function (card) {
                                                return card.name == 'tengjia' || get.value(card, target) > 0;
                                            }) > 0
                                                ? -0.5
                                                : 2.5;
                                        var js = target.getCards('j');
                                        if (js.length) {
                                            var jj = js[0].viewAs ? { name: js[0].viewAs } : js[0];
                                            if (jj.name == 'xwjh_card_toutianhuanri') return 3 + 1;
                                            if (js.length == 1 && get.effect(target, jj, target, player) >= 0) {
                                                return -1.5 + 1;
                                            }
                                            return 3 + 1;
                                        }
                                        return -1.5 + 1;
                                    },
                                    player(player, target) {
                                        if (get.attitude(player, target) < 0 && !target.countCards('he')) {
                                            return 0;
                                        }
                                        if (get.attitude(player, target) > 0) {
                                            var js = target.getCards('j');
                                            if (js.length) {
                                                var jj = js[0].viewAs ? { name: js[0].viewAs } : js[0];
                                                if (jj.name == 'xwjh_card_toutianhuanri') return 1;
                                                if (js.length == 1 && get.effect(target, jj, target, player) >= 0) {
                                                    return 0;
                                                }
                                                return 1;
                                            }
                                            return 0;
                                        }
                                        return 1;
                                    },
                                },
                            },
                        },
