                                if (
                                    game.hasPlayer(function (current) {
                                        return current.hasSkill('xwjh_lizhu');
                                    })
                                ) {
                                    if (card.number >= 10 && card.number <= 13) {
                                        return -3;
                                    }
                                }
                                if (get.color(card) == 'red' && card.number >= 10 && card.number <= 13) {
                                    return -3;
                                }
                                return 0;
