                        xwjh_card_huoshuidongyin: {
                            image: 'ext:玄武江湖/xwjh_card_huoshuidongyin.png',
                            audio: 'ext:玄武江湖',
                            type: 'trick',
                            fullskin: true,
                            enable(card, player) {
                                return true;
                            },
                            selectTarget: 1,
                            filterTarget(card, player, target) {
                                var buffs = get.xwBuffs(player, false);
                                if (buffs && buffs.length) {
                                    return true;
                                }
                                if (player.countMark('xwjh_publicmark_haibu')) {
                                    return true;
                                }
                                return player != target && target.countCards('he') > 0;
                            },
                            ai: {
                                wuxie(target, card, player, viewer) {
                                    if (player == game.me && get.attitude(viewer, player) > 0) {
                                        return 0;
                                    }
                                },
                                basic: {
                                    order: 7,
                                    useful: 1,
                                    value: 3,
                                },
                                result: {
                                    target(player, target) {
                                        var value = 0.5;
                                        value += player.countMark('xwjh_publicmark_haibu');
                                        var buffs = get.xwBuffNums(player, false);
                                        for (var i in buffs) {
                                            value += buffs[i];
                                        }
                                        return -value;
                                    },
                                    player(player, target) {
                                        var value = 0;
                                        value += player.countMark('xwjh_publicmark_haibu');
                                        var buffs = get.xwBuffNums(player, false);
                                        for (var i in buffs) {
                                            value += buffs[i];
                                        }
                                        return value;
                                    },
                                },
                            },
                            content() {
                                'step 0';
                                var countHaibu = player.countMark('xwjh_publicmark_haibu');
                                if (countHaibu) {
                                    player.removeMark('xwjh_publicmark_haibu', countHaibu);
                                    target.addMark('xwjh_publicmark_haibu', countHaibu);
                                    event.haibuOk = true;
                                    if (countHaibu >= 6 && player != target) {
                                        if (target == game.me) {
                                            window.xwTempGainAchievement('背黑锅', { text: '被使用祸水东引,转移了至少六个海捕标记.', hard: 4, extra: '捕快只管抓人,哪管你委屈不委屈.' });
                                        } else if (player == game.me) {
                                            window.xwTempGainAchievement('甩黑锅', { text: '使用祸水东引,转移了至少六个海捕标记.', hard: 4, extra: '官爷,都是他干的,和我一点关系也没有!' });
                                        }
                                    }
                                }
                                ('step 1');
                                var buffs = get.xwBuffs(player, false);
                                if (buffs.length == 0) {
                                    event.goto(3);
                                    return;
                                }
                                event.neOk = true;
                                event.buffObj = get.xwBuffNums(player, false);
                                game.removeXwBuff(player, event.buffObj);
                                ('step 2');
                                game.addXwBuff(target, event.buffObj);
                                ('step 3');
                                if (!event.haibuOk && !event.neOk) {
                                    target.chooseToDiscard(1, 'he', true);
                                }
                            },
                        },
