                        xwjh_card_haoranqi: {
                            image: 'ext:玄武江湖/xwjh_card_haoranqi.png',
                            audio: 'ext:玄武江湖',
                            type: 'xwjh_miji',
                            fullskin: true,
                            modTarget(card, player, target) {
                                if (target.hasSkill('xwjh_mijiforbid')) {
                                    return false;
                                }
                                if (get.xwIsNeigong('xwjh_haoranqi')) {
                                    if (get.xwHasNeigong(target)) {
                                        return false;
                                    }
                                } else {
                                    if (get.xwHasWaigong(target)) {
                                        return false;
                                    }
                                }
                                return true;
                            },
                            enable(card, player) {
                                if (player.hasSkill('xwjh_mijiforbid')) {
                                    return false;
                                }
                                if (get.xwIsNeigong('xwjh_haoranqi')) {
                                    if (get.xwHasNeigong(player)) {
                                        return false;
                                    }
                                } else {
                                    if (get.xwHasWaigong(player)) {
                                        return false;
                                    }
                                }
                                return true;
                            },
                            selectTarget: -1,
                            toself: true,
                            chongzhu: true,
                            filterTarget(card, player, target) {
                                if (target.hasSkill('xwjh_mijiforbid')) {
                                    return false;
                                }
                                if (get.xwIsNeigong('xwjh_haoranqi')) {
                                    if (get.xwHasNeigong(target)) {
                                        return false;
                                    }
                                } else {
                                    if (get.xwHasWaigong(target)) {
                                        return false;
                                    }
                                }
                                return target == player;
                            },
                            content() {
                                'step 0';
                                if (target.hasSkill('xwjh_mijiforbid')) {
                                    event.finish();
                                    return;
                                }
                                if (!target.hasSkill('xwjh_mijijineng')) {
                                    target.addSkill('xwjh_mijijineng');
                                }
                                var b = get.xwIsNeigong('xwjh_haoranqi');
                                var has = b ? get.xwHasNeigong(target) : get.xwHasWaigong(target);
                                if (!has) {
                                    for (var i = 0; i < target.storage.xwjh_mijijineng.length; i++) {
                                        var sk = target.storage.xwjh_mijijineng[i];
                                        if (b && get.xwIsNeigong(sk)) {
                                            target.storage.xwjh_mijijineng.splice(i, 1);
                                            i--;
                                        } else if (!b && get.xwIsWaigong(sk)) {
                                            target.storage.xwjh_mijijineng.splice(i, 1);
                                            i--;
                                        }
                                    }
                                    target.storage.xwjh_mijijineng.push('xwjh_haoranqi');
                                    target.addAdditionalSkill('xwjh_mijijineng', 'xwjh_haoranqi', true);
                                    game.log(target, '习得技能【', 'xwjh_haoranqi', '】.');
                                    game.playXwAudio('xwjh_mijipai', 1);
                                } else {
                                    var sname = b ? get.xwNeigong(target) : get.xwWaigong(target);
                                    game.log(target, '已经习得', b ? '内功' : '外功', '【', sname, '】,不能再次习得.');
                                }
                            },
                            ai: {
                                basic: {
                                    order: 15,
                                    useful: 2.0,
                                    value: 5.0,
                                },
                                result: {
                                    target(player, target) {
                                        if (target.xwjhMaxMp < 4) {
                                            return 0;
                                        }
                                        return 2;
                                    },
                                },
                            },
                        },
