                                    if (!player.storage.xwjh_card_linglongjijianhe_skill) {
                                        player.storage.xwjh_card_linglongjijianhe_skill = [];
                                    } //QQQ
                                    player.storage.xwjh_card_linglongjijianhe_skill = player.storage.xwjh_card_linglongjijianhe_skill.concat(result.links);
                                    player.markSkill('xwjh_card_linglongjijianhe_skill');
                                    player.markSkill('xwjh_card_linglongjijianhe_skill');
                                    game.log(player, '将', result.links, '放在了【玲珑机箭盒】上.');
