                                ('step 2');
                                if (result && result.targets && result.targets.length) {
                                    event.tar = result.targets[0];
                                }
                                ('step 3');
                                if (!event.tar) {
                                    event.finish();
                                    return;
                                }
                                player.line(event.tar, 'green');
                                player.equip(event.tar.getEquip(1));
                                ('step 4');
                                var tar = event.tar;
                                player.chooseBool('是否对' + get.translation(event.tar) + '造成两点伤害？').set('ai', function () {
                                    return get.attitude(player, tar) < 0 && get.xwDamageEffect(tar, player, player, null, 2) > 0;
                                });
                                ('step 5');
                                if (result && result.bool) {
                                    event.tar.damage(2, player).xwjh_jiren_cj = true;
                                }
