                        xwjh_dazhi: {
                            audio: 'ext:玄武江湖/audio:2',
                            trigger: {
                                player: 'phaseJieshuEnd',
                            },
                            mark: true,
                            markimage: 'extension/玄武江湖/image/xwjh_icon_dazhi.jpg',
                            intro: {
                                name: '达智',
                                content(storage, player) {
                                    if (player.isUnderControl(true)) {
                                        return get.translation(storage);
                                    }
                                    return '';
                                },
                                onunmark(storage, player) {
                                    player.$throw(storage, 1000);
                                    game.cardsDiscard(storage);
                                    game.log('达智牌', storage, '被置入了弃牌堆');
                                    delete player.storage.xwjh_dazhi;
                                },
                                mark(dialog, storage, player) {
                                    if (player.isUnderControl(true)) {
                                        if (player.storage.xwjh_dazhi && player.storage.xwjh_dazhi.length) {
                                            dialog.addAuto(player.storage.xwjh_dazhi);
                                        } else {
                                            return '无';
                                        }
                                    } else {
                                        return '仅' + get.translation(player) + '可见.';
                                    }
                                },
                            },
                            init(player) {
                                player.storage.xwjh_dazhi = [];
                            },
                            filter(event, player) {
                                return player.storage.xwjh_dazhi.length <= 20;
                            },
                            check(event, player) {
                                return true;
                            },
                            content() {
                                'step 0';
                                event.ccards = get.cards(4);
                                game.cardsGotoOrdering(event.ccards);
                                ('step 1');
                                var num = 20 - player.storage.xwjh_dazhi.length;
                                if (num >= 4) {
                                    num = 4;
                                }
                                player
                                    .chooseCardButton([1, num], '请选择' + get.cnNumber(1) + '至' + get.cnNumber(num) + '张牌放入独立牌堆底部(按点选顺序).', event.ccards)
                                    .set('filterButton', function (button) {
                                        return true;
                                    })
                                    .set('ai', function (button) {
                                        return 10 + Math.random() * 5;
                                    });
                                ('step 2');
                                if (result && result.links && result.links.length) {
                                    game.cardsGotoSpecial(result.links);
                                    player.storage.xwjh_dazhi = player.storage.xwjh_dazhi.concat(result.links);
                                    game.log(player, '将牌堆顶' + get.cnNumber(result.links.length) + '张牌放入独立牌堆.');
                                    player.markSkill('xwjh_dazhi');
                                }
                            },
                            group: ['xwjh_dazhi_judge', 'xwjh_dazhi_draw'],
                            subSkill: {
                                judge: {
                                    trigger: {
                                        global: 'judge',
                                    },
                                    prompt(event, player) {
                                        return get.translation(event.player) + '正在进行' + (event.judgestr || ' ') + '判定,结果为' + get.translation(event.player.judging[0]) + ',是否打出你的独立牌堆顶的' + get.translation(player.storage.xwjh_dazhi[0]) + '修改此判定牌？';
                                    },
                                    filter(event, player) {
                                        if (player.storage.xwjh_dazhi.length <= 0) {
                                            return false;
                                        }
                                        var card = player.storage.xwjh_dazhi[0];
                                        var mod2 = game.checkMod(card, player, 'unchanged', 'cardEnabled2', player);
                                        if (mod2 != 'unchanged') return mod2;
                                        var mod = game.checkMod(card, player, 'unchanged', 'cardRespondable', player);
                                        if (mod != 'unchanged') return mod;
                                        return true;
                                    },
                                    check(event, player) {
                                        var card = player.storage.xwjh_dazhi[0];
                                        var val = event.judge(card);
                                        var valo = event.judge(event.player.judging[0]);
                                        if (val > valo) {
                                            return get.attitude(player, event.player) > 0;
                                        }
                                        if (val < valo) {
                                            return get.attitude(player, event.player) < 0;
                                        }
                                        return false;
                                    },
                                    content() {
                                        'step 0';
                                        event.dazhiCard = player.storage.xwjh_dazhi.shift();
                                        player.markSkill('xwjh_dazhi');
                                        player.respond(event.dazhiCard, 'highlight', 'noOrdering');
                                        game.playXwAudio('xwjh_dazhi', 2);
                                        ('step 1');
                                        game.cardsDiscard(trigger.player.judging[0]);
                                        trigger.player.judging[0] = event.dazhiCard;
                                        trigger.orderingCards.add(event.dazhiCard);
                                        game.log(trigger.player, '的判定牌改为', event.dazhiCard, '.');
                                    },
                                },
                                draw: {
                                    trigger: {
                                        global: 'phaseDrawBegin2',
                                    },
                                    prompt(event, player) {
                                        return get.translation(event.player) + '准备执行摸牌阶段,是否将' + get.translation(player.storage.xwjh_dazhi.slice(0, event.num)) + '放在牌堆顶？';
                                    },
                                    filter(event, player) {
                                        var num = event.num;
                                        return num > 0 && num <= player.storage.xwjh_dazhi.length;
                                    },
                                    check(event, player) {
                                        var att = get.attitude(player, event.player);
                                        var num = event.num;
                                        var topcards = player.storage.xwjh_dazhi.slice(0, num);
                                        var val = get.value(topcards);
                                        if (att > 0) {
                                            return val > 20;
                                        }
                                        if (att < 0) {
                                            return val < 12.5;
                                        }
                                        return false;
                                    },
                                    content() {
                                        'step 0';
                                        game.playXwAudio('xwjh_dazhi', 2);
                                        event.putTopCards = player.storage.xwjh_dazhi.slice(0, trigger.num);
                                        player.storage.xwjh_dazhi = player.storage.xwjh_dazhi.slice(trigger.num);
                                        player.markSkill('xwjh_dazhi');
                                        for (var i = event.putTopCards.length - 1; i >= 0; i--) {
                                            var card = event.putTopCards[i];
                                            card.fix();
                                            ui.cardPile.insertBefore(card, ui.cardPile.firstChild);
                                        }
                                        game.log(player, '将' + get.cnNumber(event.putTopCards.length) + '张牌放在牌堆顶.');
                                    },
                                },
                            },
                        },
