                        xwjh_tianju: {
                            audio: 'ext:玄武江湖/audio:2',
                            charlotte: true,
                            trigger: {
                                player: 'phaseZhunbeiBegin',
                            },
                            group: ['xwjh_tianju_dying'],
                            check(event, player) {
                                var countGain = 0;
                                var countGive = 0;
                                var players = game.filterPlayer(function (current) {
                                    return current != player;
                                });
                                for (var pl of players) {
                                    countGain = countGain + pl.countCards('h');
                                    countGive = countGive + pl.hp;
                                }
                                return countGive - countGain <= 1;
                            },
                            content() {
                                'step 0';
                                var players = game.filterPlayer(function (current) {
                                    return current != player;
                                });
                                players.sortBySeat();
                                for (var p of players) {
                                    player.gain(p.getGainableCards(player, 'h'), 'give');
                                }
                                ('step 1');
                                var players = game.filterPlayer(function (current) {
                                    return current != player;
                                });
                                event.tars = players.slice(0);
                                event.tars.sortBySeat();
                                ('step 2');
                                if (event.tars.length == 0) {
                                    event.finish();
                                    return;
                                }
                                var tar = event.tars[0];
                                var gn = tar.hp;
                                if (gn > player.countCards('he')) {
                                    gn = player.countCards('he');
                                }
                                if (gn <= 0) {
                                    event.goto(4);
                                    return;
                                }
                                player.chooseCard(true, 'he', gn, '请选择交给' + get.translation(tar) + '的牌').set('ai', function (card) {
                                    return 20 - get.value(card);
                                });
                                ('step 3');
                                if (result && result.cards && result.cards.length) {
                                    player.give(result.cards, event.tars[0]);
                                    player.line(event.tars[0], 'green');
                                }
                                ('step 4');
                                event.tars.shift();
                                event.goto(2);
                            },
                            subSkill: {
                                dying: {
                                    usable: 1,
                                    trigger: {
                                        player: 'dying',
                                    },
                                    filter(event, player) {
                                        return true;
                                    },
                                    check(event, player) {
                                        return true;
                                    },
                                    content() {
                                        var players = game.filterPlayer(function (current) {
                                            return current != player;
                                        });
                                        players.sortBySeat();
                                        for (var p of players) {
                                            player.gain(p.getGainableCards(player, 'h'), 'give');
                                        }
                                    },
                                },
                            },
                        },
