                        xwjh_spyuwen_rushi: {
                            enable: 'phaseUse',
                            filterCard: true,
                            selectCard: [1, 2],
                            usable: 1,
                            discard: false,
                            lose: false,
                            delay: 0,
                            filterTarget(card, player, target) {
                                return player != target;
                            },
                            check(card) {
                                //if(ui.selected.cards.length>1) return 0;
                                //if(ui.selected.cards.length&&ui.selected.cards[0].name=='du') return 0;
                                if (card.name == 'du') return 20;
                                var player = get.owner(card);
                                var players = game.filterPlayer();
                                for (var i = 0; i < players.length; i++) {
                                    if (players[i].hasSkill('haoshi') && !players[i].isTurnedOver() && !players[i].hasJudge('lebu') && get.attitude(player, players[i]) >= 3 && get.attitude(players[i], player) >= 3) {
                                        return 11 - get.value(card);
                                    }
                                }
                                if (player.countCards('h') > player.hp) return 10 - get.value(card);
                                if (player.countCards('h') > 2) return 6 - get.value(card);
                                return -1;
                            },
                            content() {
                                target.gain(cards, player, 'giveAuto');
                                player.say(['江湖危亡,没有人能独善其身.', '我等亦有救世安民之心!'].randomGet());
                            },
                            ai: {
                                order: 1,
                                result: {
                                    target(player, target) {
                                        if (target.hasSkillTag('nogain')) return 0;
                                        if (ui.selected.cards.length && ui.selected.cards[0].name == 'du') {
                                            if (target.hasSkillTag('nodu')) return 0;
                                            return -10;
                                        }
                                        if (target.hasJudge('lebu')) return 0;
                                        if (target.hasJudge('xwjh_card_biguanqingxiu')) return 1;
                                        return 2;
                                    },
                                },
                            },
                        },
                        xwjh_tiangong: {
                            audio: 'ext:玄武江湖/audio:2',
                            trigger: {
                                player: 'phaseZhunbeiBegin',
                            },
                            derivation: ['xwjh_card_xiangong_skill', 'xwjh_card_jugulingyunti_skill', 'xwjh_card_modaojihu_skill_a', 'xwjh_card_longguqianlizhou_skill'],
                            check(event, player) {
                                return true;
                            },
                            filter(event, player) {
                                return true;
                            },
                            content() {
                                'step 0';
                                player
                                    .chooseTarget(1, '请选择要装备的角色.', function (card, player, target) {
                                        if (player == target) {
                                            return !player.isDisabled(1) || !player.isDisabled(2) || !player.isDisabled(4) || !player.isDisabled(5);
                                        } else {
                                            return !target.isDisabled(2) || !target.isDisabled(4) || !target.isDisabled(5);
                                        }
                                    })
                                    .set('ai', function (target) {
                                        if (get.attitude(player, target) <= 0) {
                                            return -10;
                                        }
                                        var val = 8 - target.countCards('e') + (player == target ? 2 : 0);
                                        if (target.hasSkill('xwjh_wudongjing')) {
                                            val = val + (player == target ? 2 : 1);
                                        }
                                        return val;
                                    });
                                ('step 1');
                                if (result && result.targets && result.targets.length) {
                                    event.tar = result.targets[0];
                                } else {
                                    event.finish();
                                }
                                ('step 2');
                                var list = [];
                                if (!event.tar.isDisabled(2)) {
                                    list.push('xwjh_card_jugulingyunti');
                                }
                                if (!event.tar.isDisabled(4)) {
                                    list.push('xwjh_card_longguqianlizhou');
                                }
                                if (!event.tar.isDisabled(5)) {
                                    list.push('xwjh_card_modaojihu');
                                }
                                if (event.tar == player && !event.tar.isDisabled(1)) {
                                    list.push('xwjh_card_xiangong');
                                }
                                event.list = list;
                                event.okList = [];
                                event.climit = event.tar == player ? 2 : 1;
                                ('step 3');
                                if (event.okList.length >= event.climit || event.list.length == 0) {
                                    event.goto(5);
                                    return;
                                }
                                var li = event.list;
                                var tar = event.tar;
                                player
                                    .chooseControl(event.list)
                                    .set('prompt', '请选择你要令' + get.translation(event.tar) + '装备的牌.')
                                    .set('ai', function () {
                                        for (var i = 0; i < li.length; i++) {
                                            var m = li[i];
                                            if (m == 'xwjh_card_xiangong' && !player.getEquip(1)) {
                                                return m;
                                            }
                                            if (m == 'xwjh_card_modaojihu' && !player.getEquip(5)) {
                                                return m;
                                            }
                                            if (m == 'xwjh_card_jugulingyunti' && !player.getEquip(2)) {
                                                return m;
                                            }
                                            if (m == 'xwjh_card_longguqianlishou' && !player.getEquip(4)) {
                                                return m;
                                            }
                                        }
                                        return li.randomGet();
                                    });
                                ('step 4');
                                if (result && result.control) {
                                    event.okList.push(result.control);
                                    event.list.remove(result.control);
                                    event.goto(3);
                                }
                                ('step 5');
                                for (var i = 0; i < event.okList.length; i++) {
                                    //player.useCard(game.createCard("xwjh_card_linglongjijianhe",'club',7),player);
                                    var suit = {
                                        xwjh_card_xiangong: 'diamond',
                                        xwjh_card_longguqianlizhou: 'spade',
                                        xwjh_card_modaojihu: 'club',
                                        xwjh_card_jugulingyunti: 'heart',
                                    };
                                    var number = {
                                        xwjh_card_xiangong: 3,
                                        xwjh_card_longguqianlizhou: 5,
                                        xwjh_card_modaojihu: 6,
                                        xwjh_card_jugulingyunti: 4,
                                    };
                                    var card = game.createCard(event.okList[i], suit[event.okList[i]], number[event.okList[i]]);
                                    event.tar.equip(card);
                                }
                            },
                        },
