                        xwjh_baitang: {
                            audio: 'ext:玄武江湖/audio:2',
                            enable: 'phaseUse',
                            usable: 1,
                            selectTarget: 1,
                            selectCard: 1,
                            filterCard(card) {
                                return get.color(card) == 'black';
                            },
                            check(card) {
                                return 20 - get.value(card);
                            },
                            position: 'he',
                            filterTarget(card, player, target) {
                                return player != target;
                            },
                            filter(event, player) {
                                return !player.hasSkill('xwjh_baitang_off0') && !player.hasSkill('xwjh_baitang_off1') && player.countCards('he', { color: 'black' }) > 0;
                            },
                            ai: {
                                order: 24,
                                result: {
                                    target(player, target) {
                                        var eft = get.xwDamageEffect(target, player, target);
                                        if (get.xwDamageEffect(target, player, target) >= 0) {
                                            return eft;
                                        }
                                        if (get.attitude(player, target) < 0) {
                                            var count1 = game.countPlayer(function (current) {
                                                return current.countCards('h') > 0 && current.inRange(target) && current != target && get.attitude(player, target) < 0;
                                            });
                                            var count2 = game.countPlayer(function (current) {
                                                return current.countCards('h') > 0 && current.inRange(target) && current != target && get.attitude(player, target) > 0;
                                            });
                                            if (count2 > count1) {
                                                return count1 * 2 - count2 * 2;
                                            }
                                            return count2 - count1;
                                        }
                                        return -2;
                                    },
                                },
                            },
                            group: ['xwjh_baitang_end'],
                            subSkill: {
                                off0: {
                                    charlotte: true,
                                },
                                off1: {
                                    charlotte: true,
                                },
                                end: {
                                    popup: false,
                                    forced: true,
                                    charlotte: true,
                                    trigger: {
                                        player: 'phaseUseEnd',
                                    },
                                    filter(event, player) {
                                        return player.hasSkill('xwjh_baitang_off0') || player.hasSkill('xwjh_baitang_off1');
                                    },
                                    content() {
                                        if (player.hasSkill('xwjh_baitang_off0')) {
                                            player.removeSkill('xwjh_baitang_off0');
                                            player.addSkill('xwjh_baitang_off1');
                                        } else {
                                            player.removeSkill('xwjh_baitang_off1');
                                        }
                                    },
                                },
                            },
                            content() {
                                'step 0';
                                event.players = game
                                    .filterPlayer(function (current) {
                                        return current.inRange(target) && current != target;
                                    })
                                    .sortBySeat();
                                event.ppls = [];
                                event.idx = 0;
                                event.trueCount = 0;
                                ('step 1');
                                if (!event.players.length) {
                                    event.goto(5);
                                    return;
                                }
                                var cur = event.players.shift();
                                event.cur = cur;
                                if (!cur.isIn() || cur.countCards('h') == 0) {
                                    event.goto(4);
                                    return;
                                }
                                var p = player;
                                var sel = [1, 1];
                                if (cur == player && player.storage.xwjh_mingzhu_ok) {
                                    sel = [1, 2];
                                }
                                cur.chooseCard(true, sel, '请选择将其放在牌堆顶的牌', 'h', function (card) {
                                    return true;
                                }).set('ai', function (card) {
                                    var att = get.attitude(cur, target);
                                    if (card.number % 2 != 0) {
                                        if (att < 0) {
                                            return 20;
                                        } else if (att >= 0) {
                                            return -20;
                                        }
                                    }
                                    if (card.number % 2 == 0) {
                                        if (att < 0) {
                                            return -20;
                                        } else if (att >= 0) {
                                            return 20;
                                        }
                                    }
                                    return 20 - get.value(card);
                                });
                                ('step 2');
                                if (result && result.cards && result.cards.length) {
                                    event.cur.lose(result.cards, ui.special, 'toStorage');
                                    event.ppls.push(event.cur);
                                    event.xcard = result.cards;
                                    event.trueCount += result.cards.length;
                                    game.log(event.cur, '将' + get.cnNumber(result.cards.length) + '张牌放在了牌堆顶.');
                                } else {
                                    event.goto(4);
                                }
                                ('step 3');
                                for (var i = 0; i < event.xcard.length; i++) {
                                    event.xcard[i].fix();
                                    ui.cardPile.insertBefore(event.xcard[i], ui.cardPile.firstChild);
                                }
                                ('step 4');
                                event.idx++;
                                event.goto(1);
                                ('step 5');
                                event.showCards = get.cards(event.trueCount);
                                player.showCards(event.showCards, '拜堂');
                                event.redCount = 0;
                                event.blackCount = 0;
                                for (var i = 0; i < event.showCards.length; i++) {
                                    if (event.showCards[i].number % 2 == 0) {
                                        event.blackCount++;
                                    }
                                    if (event.showCards[i].number % 2 != 0) {
                                        event.redCount++;
                                    }
                                }
                                event.dam = event.redCount - event.blackCount;
                                if (event.dam < 0) {
                                    event.dam = 0;
                                }
                                game.cardsDiscard(event.showCards);
                                ('step 6');
                                game.log(target, '即将受到', event.dam, '点伤害.');
                                if (event.dam > 0) {
                                    target.damage(event.dam, player);
                                }
                                if (player == game.me) {
                                    if (event.dam == 0) {
                                        window.xwTempGainAchievement('拜个假堂');
                                    } else if (event.dam >= 5) {
                                        window.xwTempGainAchievement('喋血红娘');
                                    }
                                }
                                ('step 7');
                                if (event.dam > 1) {
                                    player.addSkill('xwjh_baitang_off0');
                                    for (var i = 0; i < event.ppls.length; i++) {
                                        if (event.ppls[i].isIn()) {
                                            event.ppls[i].draw();
                                        }
                                    }
                                }
                            },
                        },
