                                for (var i = 0; i < event.cards2.length; i++) {
                                    if (player.storage.xwjh_xinnuo.includes(event.cards2[i])) {
                                        regain.push(event.cards2[i]);
                                    }
                                }
                                var next = game.createEvent('xinnuoRegain', false);
                                next.player = player;
                                next.regain = regain;
                                next.setContent(function () {
                                    var reregain = [];
                                    for (var i = 0; i < this.regain.length; i++) {
                                        var pos = get.position(this.regain[i]);
                                        if (pos && pos != 's') {
                                            reregain.push(this.regain[i]);
                                        }
                                    }
                                    for (var i = 0; i < reregain.length; i++) {
                                        this.regain.remove(reregain[i]);
                                    }
                                    if (reregain.length) {
                                        var owner = get.owner(reregain[0]);
                                        if (owner) {
                                            player.gain(reregain, owner);
                                        } else {
                                            player.gain(reregain);
                                        }
                                        player.$gain2(reregain, true);
                                    }
                                    if (player.storage.xwjh_xinnuo) {
                                        for (var i = 0; i < this.regain.length; i++) {
                                            if (player.storage.xwjh_xinnuo.includes(this.regain[i])) {
                                                player.storage.xwjh_xinnuo.remove(this.regain[i]);
                                                game.xwUnmarkCard(this.regain[i], 'xwjh_xinnuo');
                                            }
                                        }
                                    }
                                    player.markSkill('xwjh_xinnuo');
                                    if (player.storage.xwjh_xinnuo_used) {
                                        for (var i = 0; i < this.regain.length; i++) {
                                            if (player.storage.xwjh_xinnuo_used.includes(this.regain[i])) {
                                                player.storage.xwjh_xinnuo_used.remove(this.regain[i]);
                                            }
                                        }
                                    }
                                    player.markSkill('xwjh_xinnuo_used');
                                });
