                                    str += player.maxHp - player.hp;
                                    str += '张牌并弃置';
                                    str += player.hp;
                                    str += '张牌？否则';
                                    str += get.translation(event.tar);
                                    str += '摸';
                                    str += player.hp;
                                    str += '张牌并弃置';
                                    str += player.maxHp - player.hp;
                                    str += '张牌.';
                                    var tar1 = event.tar;
