                            logTarget(event, player) {
                                if (event.player == player) return event.source;
                                return event.player;
                            },
                            filter(event, player) {
                                if (event.source == event.player) return false;
                                if (event.source == player && !event.player.isIn()) return false;
                                if (event.player == player && (!event.source || !event.source.isIn())) return false;
                                var target;
                                if (event.player == player) {
                                    target = event.source;
                                } else {
                                    target = event.player;
                                }
                                if (target.xwjhMp <= 0 || player.xwjhMp >= player.xwjhMaxMp) {
                                    return player.xwjhMaxMp < 7;
                                }
                                return true;
                            },
