                            check(event, player) {
                                if (event.card.name == 'xwjh_card_qingchaoerchu' || event.card.name == 'xwjh_card_sheiyuzhengfeng' || event.card.name == 'nanman') {
                                    return (
                                        event.targets.filter(function (current) {
                                            return get.attitude(player, current) < 0 && current.hp <= 1;
                                        }).length >
                                        event.targets.filter(function (current) {
                                            return get.attitude(player, current) > 0 && current.hp <= 1;
                                        }).length
                                    );
                                }
                                var val1 = 0;
                                var val2 = 0;
                                for (var target of event.targets) {
                                    val1 += get.effect(target, event.card, player, player);
                                }
                                _status.xwjh_manao_directhit = true;
                                for (var target of event.targets) {
                                    var add = get.effect(target, event.card, player, player);
                                    if (event.card.name == 'sha' && get.attitude(player, target) < 0 && target.countCards('h') >= 2) {
                                        add *= 1.1;
                                    }
                                    val2 += add;
                                }
                                delete _status.xwjh_manao_directhit;
                                return val1 < val2;
                            },
                            ai: {
                                directHit_ai: true,
                                skillTagFilter(player, tag, arg) {
                                    return _status.xwjh_manao_directhit;
                                },
                            },
